"""Build the illustrated, self-contained Student108 standard lesson mission."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
IMAGES = json.loads((ROOT / 'authoring/images.json').read_text(encoding='utf-8'))
STEPS = []
CSS = '''body{font:19px/1.65 Arial,sans-serif;color:#20354c;background:white;margin:0;padding:24px;max-width:920px;box-sizing:border-box}p{margin:16px 0}h3{font-size:23px;color:#156b82;margin:24px 0 10px}strong{color:#155e75}li{margin:8px 0}figure{margin:20px 0;padding:16px;background:#f1f7fa;border:1px solid #dce7ee;border-radius:16px;text-align:center}figure img{display:block;max-width:100%;width:auto;height:auto;max-height:320px;margin:auto;object-fit:contain}figcaption{font-size:14px;line-height:1.45;color:#52687d;margin-top:10px}.compact img{max-height:145px}.gallery{display:flex;flex-wrap:wrap;gap:12px}.gallery figure{flex:1 1 210px;min-width:0;margin:0}.gallery img{max-height:230px}.key{background:#e8f6ed;border-left:5px solid #3b9b74;padding:15px 19px;border-radius:8px;margin:18px 0}.example{background:#fff5df;border-left:5px solid #e6ad42;padding:15px 19px;border-radius:8px;margin:18px 0}.flow{background:#eaf2fc;padding:15px;border-radius:10px;text-align:center;font-weight:bold}table{width:100%;border-collapse:collapse;font-size:17px}td,th{border:1px solid #c8dbe5;padding:10px;text-align:left;vertical-align:top}th{background:#e7f1f7}a{color:#126797;overflow-wrap:anywhere}code{background:#edf2f7;padding:2px 5px;border-radius:4px}@media(max-width:550px){body{padding:14px}td,th{font-size:15px;padding:7px}}'''


def wrap(body):
    return '<!doctype html><html lang="bg"><head><meta charset="utf-8"><style>' + CSS + '</style></head><body>' + body + '</body></html>'


def picture(key, compact=False):
    im = IMAGES[key]
    credit = ''
    if im['license'] not in ('Public domain', 'CC0'):
        credit = ' · ' + html.escape(im['author']) + ' · <a href="' + html.escape(im['source'], quote=True) + '">източник</a> · <a href="' + html.escape(im['license_url'], quote=True) + '">' + html.escape(im['license']) + '</a>'
    return '<figure' + (' class="compact"' if compact else '') + '><img src="' + html.escape(im['url'], quote=True) + '" alt="' + html.escape(im['caption'], quote=True) + '"><figcaption>' + html.escape(im['caption']) + credit + '</figcaption></figure>'


def gallery(*keys):
    return '<div class="gallery">' + ''.join(picture(k) for k in keys) + '</div>'


def info(sid, title, body):
    STEPS.append({'id': sid, 'step_content': {'type': 'information', 'title': title, 'instruction': wrap(body), 'instruction_format': 'html'}, 'step_rules': {}})


def choice(sid, key, question, options, correct, feedback):
    assert len(options) == 6 and 1 < len(correct) < 6
    STEPS.append({'id': sid, 'step_content': {'type': 'multiple_choice', 'title': 'Провери разбирането си', 'instruction': wrap(picture(key, True) + '<p>' + question + '</p><p><strong>Избери всички верни отговори.</strong></p>'), 'instruction_format': 'html', 'options': [{'id': str(i + 1), 'text': v} for i, v in enumerate(options)], 'correct_option_ids': [str(i + 1) for i in correct], 'feedback': feedback}, 'step_rules': {'automatic_feedback': True, 'send_progress': True}})


def opened(sid, key, title, question, answer, ai=False):
    STEPS.append({'id': sid, 'step_content': {'type': 'open_answer', 'title': title, 'instruction': wrap(picture(key, True) + '<p>' + question + '</p><p>Отговори със свои думи в кратък абзац.</p>'), 'instruction_format': 'html', 'reference_answer': answer}, 'step_rules': {'send_progress': True, 'automatic_feedback': not ai, 'ai_feedback': ai}})


info('intro', 'За какво е този урок?', picture('intro') + '''<p>Телефонът в джоба ти е малък компютър. С него разговаряш, снимаш, учиш, използваш карти и обменяш информация. Таблетите и смартчасовниците също съчетават изчисления и възможности за връзка.</p><ul><li>Ще различаваш основните <strong>мобилни устройства</strong> и ще проследиш развитието им.</li><li>Ще обясняваш как телефонът използва <strong>клетъчната мрежа</strong> и какво означават поколенията 1G–5G.</li><li>Ще разпознаваш <strong>Android, iOS и HarmonyOS</strong>.</li><li>Ще избираш между <strong>Wi-Fi, Bluetooth и GPS</strong> според задачата.</li></ul>''')

info('mobile-devices', 'Какво е мобилно устройство?', picture('devices') + '''<p><strong>Мобилно устройство</strong> е преносимо изчислително устройство, което можем да използваме на различни места. То има процесор, памет, екран и захранване от батерия. <strong>Операционната система</strong> управлява устройството и осигурява работата на приложенията.</p><p><strong>Мобилно приложение</strong> е програма за конкретна задача: например рисуване, съобщения, снимане или навигация. Някои приложения работят и без интернет, а други се нуждаят от връзка.</p><p>При <strong>сензорен екран</strong> задаваш действия чрез докосване. Докосваш икона, за да отвориш приложение, плъзгаш пръст, за да прелистиш, и използваш <strong>виртуална клавиатура</strong>, показана на екрана, за да пишеш.</p><div class="example">В приложението за бележки записваш домашната работа. Устройството е телефонът, приложението е програмата за бележки, а клавиатурата върху екрана е средство за въвеждане.</div>''')
choice('mobile-check', 'devices', 'Кои твърдения за мобилните устройства са верни?', ['Мобилното устройство може да се използва на различни места.', 'Операционната система управлява устройството.', 'Мобилното приложение е вид батерия.', 'Виртуалната клавиатура се показва на екрана.', 'Всяко приложение задължително изисква интернет.', 'Докосването на икона може да отвори приложение.'], [0, 1, 3, 5], 'Устройството е преносимо, операционната система го управлява, а приложенията изпълняват задачи. Виртуалната клавиатура е на екрана. Част от приложенията работят и без интернет.')

info('types', 'Видове мобилни устройства', gallery('devices', 'watch') + '''<table><tr><th>Вид</th><th>Особеност и пример за използване</th></tr><tr><td><strong>Лаптоп</strong></td><td>Преносим компютър с екран и физическа клавиатура. Удобен за писане на доклад. Ноутбук и нетбук са названия за видове преносими компютри.</td></tr><tr><td><strong>Таблет</strong></td><td>Компютър със сензорен екран. Обикновено се използва с виртуална клавиатура; може да се свърже и външна. Подходящ за четене и рисуване.</td></tr><tr><td><strong>Смартфон</strong></td><td>Мобилен телефон с операционна система и приложения. Съчетава разговори и много компютърни функции.</td></tr><tr><td><strong>Носимо устройство</strong></td><td>Носи се на тялото: смартчасовник, фитнес гривна или някои видове умни очила.</td></tr><tr><td><strong>Други преносими устройства</strong></td><td>Електронен четец за книги, цифров фотоапарат и камера — по-специализирани задачи.</td></tr></table><p>Очила за виртуална реалност също са пример за носима техника. Пейджърите получават кратки съобщения, а смарткартите съдържат чип за съхраняване и обработване на данни. Те са по-специализирани от смартфона.</p><div class="key">Избираме устройство според задачата: дълъг текст — лаптоп; удобно четене — таблет или четец; разговори в движение — смартфон.</div>''')
choice('types-check', 'watch', 'Кои съчетания между устройство и описание са правилни?', ['Смартфон — телефон с операционна система и приложения.', 'Смартчасовник — носимо устройство.', 'Електронен четец — устройство основно за телефонни разговори.', 'Лаптоп — преносим компютър с физическа клавиатура.', 'Таблет — устройство, към което никога не може да се свърже клавиатура.', 'Цифров фотоапарат — специализирано устройство за снимки.'], [0, 1, 3, 5], 'Смартфонът съчетава телефон и приложения, часовникът се носи на тялото, лаптопът има клавиатура, а фотоапаратът служи за снимки. Четецът е предимно за книги; таблетът може да работи и с външна клавиатура.')

info('history-ideas', 'От идея до преносим компютър', picture('dynabook') + '''<p>Мобилните компютри не се появяват изведнъж. Първо възниква идеята човек да носи със себе си устройство за писане, четене и общуване.</p><p>Още през XIX век <strong>телеаутографът</strong> предава ръкопис и рисунки по проводници. Той е исторически предшественик на електронното общуване, но не е съвременен таблет.</p><p>През 1968 г. Алън Кей развива идея за преносим компютър за учене, която по-късно става известна като <strong>Dynabook</strong>. През 1972 г. я описва в публикация. На снимката виждаш макет, представящ идеята. Това не е завършен таблет, продаван с интернет и сензорен екран.</p><p>Във филма <strong>„2001: Космическа одисея“</strong> от 1968 г. също се виждат устройства, напомнящи днешните таблети. Художествената представа и техническите проекти показват желанието за удобно лично устройство.</p>''')
choice('history-ideas-check', 'dynabook', 'Кои твърдения за ранните идеи са верни?', ['Dynabook е идея за преносим компютър за учене.', 'Макетът на Dynabook доказва, че устройството е било масово продаван таблет.', 'Телеаутографът предава ръкопис и рисунки по проводници.', 'Филм от 1968 г. показва устройства, напомнящи таблети.', 'Телеаутографът използва 5G.', 'Идеята за преносим компютър предхожда днешните таблети.'], [0, 2, 3, 5], 'Dynabook е концепция, представена и с макет. Телеаутографът е по-ранно устройство за предаване по проводници. И филмовите представи показват, че идеята за подобна техника съществува преди днешните продукти.')

info('history-products', 'Появяват се реални устройства', picture('palm') + '''<p>Когато електронните компоненти стават по-малки, се появяват и реални преносими устройства, управлявани с писалка или докосване.</p><table><tr><th>Година</th><th>Устройство</th><th>Място в развитието</th></tr><tr><td>1989</td><td><strong>GRiDPad</strong></td><td>Ранен таблетен компютър с управление чрез писалка.</td></tr><tr><td>1993</td><td><strong>Apple Newton</strong></td><td>Джобен цифров помощник за бележки, контакти и организация.</td></tr><tr><td>1996</td><td><strong>Palm Pilot</strong></td><td>Компактен цифров помощник за лична информация.</td></tr><tr><td>2010</td><td><strong>Apple iPad</strong></td><td>Таблет с управление чрез докосване и много приложения.</td></tr></table><p>Развитието не е само намаляване на размера. Подобряват се екраните, батериите, програмите и възможностите за връзка. Така преносимият компютър става полезен за повече задачи.</p><div class="example">По-ранният цифров помощник пази контакти и бележки. По-новият таблет съчетава тези задачи с видео, рисуване, обучение и онлайн общуване.</div>''')
choice('products-check', 'palm', 'Кои твърдения съответстват на развитието на устройствата?', ['GRiDPad е пример за ранен таблет с писалка.', 'Apple iPad се появява през 2010 г.', 'Palm Pilot е базова станция за 5G.', 'Newton и Palm са цифрови помощници.', 'Развитието засяга единствено размера на корпуса.', 'Екраните, батериите и приложенията също се развиват.'], [0, 1, 3, 5], 'GRiDPad, Newton, Palm и iPad са различни етапи в развитието на преносимите устройства. Подобряват се както размерите, така и начинът на управление, захранването и възможностите на програмите.')

info('early-smartphone', 'Ранен смартфон и днешен смартфон', gallery('simon', 'android') + '''<p><strong>IBM Simon</strong> е сред най-известните ранни смартфони. Продава се от 1994 г. Съчетава мобилен телефон, сензорен екран и функции на цифров помощник: контакти, календар, бележки и работа с факс.</p><p>Днешният смартфон запазва идеята <strong>„телефон и компютър в едно“</strong>, но добавя много по-големи възможности: цветен екран с висока разделителна способност, камери, навигация, разнообразни приложения и бърз достъп до интернет при подходяща мрежа.</p><p>За смислено сравнение използвай едни и същи показатели: <strong>управление, приложения и връзка</strong>. Не сравнявай само годината или външния вид.</p><p>Можеш да проучиш още в <a href="https://bg.wikipedia.org/wiki/IBM_Simon">статията за IBM Simon</a> и <a href="https://bg.wikipedia.org/wiki/Смартфон">статията за смартфоните</a>. Отвори връзката; с <strong>Ctrl + F</strong> потърси „1994“ или „екран“. Сверявай датите и описанията.</p><div class="example">Общо: Simon и днешният смартфон използват сензорен екран. Разлика: днешният смартфон предлага много повече приложения и по-бързи мрежови услуги.</div>''')
opened('smartphone-answer', 'simon', 'Обясни развитието на смартфона', 'Как се развива идеята „телефон и компютър в едно“ от IBM Simon до днешния смартфон, показано с обща черта и конкретни подобрения?', 'IBM Simon от 1994 г. вече съчетава телефон, сензорен екран и приложения като календар и бележки. Днешният смартфон също е телефон и компютър в едно, но има много повече приложения и по-бърз достъп до интернет при подходяща мрежа. Например можем да снимаме с камерата, да използваме навигация и да провеждаме видеоразговори. Общата идея остава, а възможностите се разширяват.', ai=True)

info('cellular', 'Как телефонът се свързва с мобилната мрежа?', picture('tower') + '''<p><strong>Мобилни комуникации</strong> наричаме безжичния обмен на информация с движещи се или преносими устройства. При клетъчната телефония телефонът изпраща и приема радиосигнали чрез близка <strong>базова станция</strong>. Значи той е и предавател, и приемник.</p><p>Всяка станция обслужва определена област. Областта на радиопокритие се нарича <strong>клетка</strong>. Много клетки заедно образуват <strong>клетъчна мрежа</strong>, която обслужва голяма територия.</p><div class="flow">Твоят телефон ↔ базова станция ↔ мрежа на оператора ↔ друг телефон или интернет</div><p>Когато се придвижваш, мрежата може да прехвърли връзката към друга станция. Клетките не са физически огради: покритието зависи от разстоянието, сградите, релефа и оборудването.</p><div class="example">В автобуса разговаряш по телефона. Докато той се движи през града, връзката може да премине между различни клетки, без да започваш разговора отначало.</div>''')
choice('cellular-check', 'tower', 'Кои твърдения описват клетъчната мрежа?', ['Телефонът обменя радиосигнали с базова станция.', 'Клетка е област на радиопокритие.', 'Всеки разговор изисква кабел от телефона до станцията.', 'Много клетки осигуряват покритие на по-голяма територия.', 'Сградите и релефът никога не влияят на сигнала.', 'При движение връзката може да премине към друга станция.'], [0, 1, 3, 5], 'Клетъчната мрежа използва радиовръзка между телефоните и базовите станции. Клетката е област на покритие. Покритието зависи от условията; при движение мрежата може да прехвърля връзката между станции.')

info('generation-12', 'От аналогов разговор до цифрови услуги', picture('simon') + '''<p>Буквата <strong>G</strong> идва от английската дума <em>Generation</em> — <strong>поколение</strong>. Всяко поколение обединява технологии с определени възможности за пренос.</p><p><strong>1G</strong> е първото поколение мобилни клетъчни системи. То се развива през края на 1970-те и 1980-те години и използва <strong>аналогова връзка за глас</strong>.</p><p><strong>2G</strong> въвежда цифрова мобилна връзка през 1990-те години. Един от основните стандарти е <strong>GSM</strong>. Появяват се повече услуги:</p><ul><li><strong>SMS</strong> — кратки текстови съобщения.</li><li><strong>MMS</strong> — мултимедийни съобщения, например със снимка.</li><li><strong>WAP</strong> — технология за достъп до уеб услуги от ранни мобилни телефони.</li><li><strong>GPRS и EDGE</strong> — технологии за развитие на преноса на данни в GSM мрежите.</li></ul><p>Тези услуги се развиват постепенно. Цифровият пренос създава основа телефонът да обменя не само глас, но и други данни.</p>''')
choice('generation-12-check', 'simon', 'Кои твърдения за 1G и 2G са верни?', ['G означава поколение.', '1G използва аналогова връзка за глас.', 'SMS е услуга само за прехвърляне на големи видеофайлове.', 'GSM е стандарт от второто поколение.', 'GPRS и EDGE развиват преноса на данни в GSM мрежите.', '2G означава два гигабайта памет.'], [0, 1, 3, 4], 'G означава поколение, а не капацитет. 1G пренася аналогов глас. 2G използва цифрови технологии като GSM; SMS са текстови съобщения, а GPRS и EDGE подобряват преноса на данни.')

info('generation-35', '3G, 4G и 5G: повече данни и нови възможности', picture('5g') + '''<p>По-новите поколения развиват мобилния интернет и обслужват повече задачи. <strong>Пренос на данни</strong> означава изпращане и получаване на информация — например снимки, звук или страници.</p><table><tr><th>Поколение</th><th>Основна промяна</th><th>Пример</th></tr><tr><td><strong>3G</strong></td><td>По-удобен мобилен интернет и мултимедийни услуги спрямо ранните 2G технологии.</td><td>Разглеждане на страници и видеоразговори.</td></tr><tr><td><strong>4G</strong></td><td>Високоскоростен пренос на данни през мрежа, използваща интернет протоколи.</td><td>Гледане на онлайн видео и разговори през приложения.</td></tr><tr><td><strong>5G</strong></td><td>Възможности за още по-високи скорости, по-малко закъснение и много свързани устройства.</td><td>Обмен на големи файлове и свързани умни устройства.</td></tr></table><p><strong>VoIP</strong> е пренос на глас чрез интернет протокола. Например приложение може да превърне гласа в данни и да ги предаде през интернет. Технологията не е ограничена само до 4G.</p><p><strong>6G</strong> е следващото поколение в процес на разработване и стандартизиране, свързано с рамката <strong>IMT-2030</strong>. Това е посока за развитие около 2030 г. и след това, а не обещание, че всеки телефон ще работи с 6G на конкретна дата.</p>''')
choice('generation-35-check', 'tower', 'Кои твърдения за поколенията и услугите са верни?', ['3G развива мобилния интернет и мултимедията.', '5G може да поддържа повече устройства и по-малко закъснение.', 'VoIP означава съхраняване на снимки само в телефона.', '4G позволява бърз обмен на данни и онлайн видео.', '6G вече е задължително във всеки телефон.', 'VoIP предава глас като данни чрез интернет протокола.'], [0, 1, 3, 5], '3G, 4G и 5G развиват преноса на данни. VoIP е пренос на глас чрез интернет протокола. 6G е бъдещо поколение в процес на разработване и стандартизиране; наличието му не следва от това, че телефонът е нов.')

info('speed', 'Как се измерва скоростта на връзката?', picture('android') + '''<p><strong>Скоростта на пренос</strong> показва колко данни се пренасят за единица време. Често се измерва в <strong>Mbit/s или Mbps — мегабита в секунда</strong>. <strong>1 Gbit/s = 1000 Mbit/s.</strong> Това са единици за скорост, а не за размера на паметта.</p><ul><li><strong>Download</strong> — получаване на данни към устройството, например изтегляне на снимка.</li><li><strong>Upload</strong> — изпращане на данни от устройството, например качване на снимка.</li><li><strong>Закъснение</strong> — времето за отговор на връзката. При тестове се показва като ping в <strong>милисекунди (ms)</strong>; по-малка стойност означава по-кратко чакане.</li></ul><p>8 бита образуват един байт. Затова <strong>80 Mbit/s съответстват на 10 MB/s</strong> преди разходите за самия пренос. Файл с размер 100 MB би се прехвърлил за около 10 секунди при постоянна скорост 10 MB/s, без да броим допълнителния обмен.</p><div class="key">Надписът „5G“ не гарантира определена скорост. Влияят сигналът, натоварването, телефонът и услугата. Теоретичните максимуми на стандартите не са обещание за резултата от конкретен тест.</div>''')
choice('speed-check', 'android', 'Кои тълкувания на скоростта са правилни?', ['Mbps измерва мегабити в секунда.', 'Upload е получаване на снимка от интернет.', 'Download е получаване на данни към устройството.', 'По-нисък ping означава по-малко закъснение.', '5G гарантира една и съща скорост навсякъде.', '80 Mbit/s съответстват на 10 MB/s преди разходите за пренос.'], [0, 2, 3, 5], 'Download получава, а upload изпраща данни. Mbps е скорост в мегабити за секунда. 8 бита = 1 байт, така че 80 Mbit/s = 10 MB/s преди допълнителния обмен. Резултатът зависи от условията, а не само от поколението.')

info('network-practice', 'Практическо наблюдение: връзка и скорост', picture('android') + '''<p>Можеш да наблюдаваш своята връзка или да използваш примерните резултати по-долу. Не е необходимо да имаш собствен смартфон.</p><ol><li>Погледни лентата за състоянието. Обозначения като <strong>4G, LTE или 5G</strong> показват мобилна технология. Знакът за <strong>Wi-Fi</strong> показва връзка с безжична локална мрежа.</li><li>Ако наблюдаваш мобилните данни, запиши означението на мрежата. Тест през Wi-Fi измерва друга връзка, а не директно клетъчната връзка на телефона.</li><li>За измерване може да отвориш <a href="https://www.speedtest.net/">Speedtest</a> в браузъра и да натиснеш <strong>Go / Старт</strong>. Запиши download, upload и ping. Тестът прехвърля данни; ако нямаш подходящ достъп, използвай готовия пример.</li></ol><table><tr><th>Примерен тест</th><th>Download</th><th>Upload</th><th>Ping</th></tr><tr><td>Мобилни данни, 4G</td><td>60 Mbit/s</td><td>15 Mbit/s</td><td>35 ms</td></tr></table><div class="example">При този тест телефонът получава данни по-бързо, отколкото ги изпраща. Резултатът описва едно измерване в конкретни условия. Той не доказва скоростта на всички 4G мрежи.</div><p>В следващата стъпка обясни какво показва примерният тест или собственото ти измерване.</p>''')
opened('network-answer', 'android', 'Разчети резултата от теста', 'Какво показва за връзката примерният тест 4G с download 60 Mbit/s, upload 15 Mbit/s и ping 35 ms или твоето собствено измерване?', 'В примерния тест получаването на данни е 60 Mbit/s, а изпращането е 15 Mbit/s, тоест получаването е по-бързо. Ping 35 ms показва закъснението на отговора при теста. Резултатите се отнасят за тази връзка и конкретния момент; не доказват скоростта на всяка 4G мрежа. При собствено измерване се посочват неговите стойности и видът на връзката.')

info('android', 'Android: операционна система за много устройства', picture('android') + '''<p><strong>Android</strong> е мобилна операционна система, развивана от Google и общност от разработчици. Използва ядрото <strong>Linux</strong> и работи на много модели смартфони и таблети от различни производители. Първият продаван телефон с Android се появява през 2008 г.</p><p><strong>Началният екран</strong> съдържа икони за отваряне на приложения. <strong>Лентата за състоянието</strong> показва например заряда на батерията и наличната връзка. Чрез докосване отваряш приложение, а с плъзгане прелистваш съдържание.</p><p>Операционната система управлява паметта, приложенията и устройствата. Например приложението „Камера“ използва възможностите, които системата предоставя за работа с камерата и за записване на снимката.</p><div class="key">Марката на телефона и операционната система са различни неща. Samsung е производител, а Android е операционна система. Външният вид на Android може да се различава според производителя и версията.</div>''')
choice('android-check', 'android', 'Кои твърдения за Android са верни?', ['Android използва ядрото Linux.', 'Android е име на батерия.', 'Телефони от различни производители могат да използват Android.', 'Лентата за състоянието може да показва заряда и връзката.', 'Всички версии на Android задължително изглеждат еднакво.', 'Приложението „Камера“ и операционната система имат различни роли.'], [0, 2, 3, 5], 'Android е операционна система, използваща Linux, а не хардуерен компонент. Използва се от различни производители. Системата управлява ресурсите; приложението изпълнява конкретна задача. Обликът може да е различен.')

info('ios', 'iOS: системата на iPhone', picture('iphone') + '''<p><strong>iOS</strong> е мобилната операционна система на Apple за <strong>iPhone</strong>. Тя управлява ресурсите на телефона и осигурява среда за приложенията. Apple разработва както телефоните iPhone, така и тяхната операционна система.</p><p>Работата използва <strong>директно взаимодействие</strong> с екрана: докосваш бутон, плъзгаш списък, местиш плъзгач за силата на звука или променяш превключвател в настройките. Началният екран съдържа икони на приложения.</p><p>Таблетите iPad днес използват <strong>iPadOS</strong> — сродна система, предназначена за тях. Затова при описване на устройство записвай точните му вид и система: <strong>iPhone — iOS; iPad — iPadOS</strong>.</p><div class="example">Натискаш иконата „Снимки“, за да разгледаш албум. „Снимки“ е приложение, а iOS е системата, която осигурява работата му на iPhone.</div>''')
choice('ios-check', 'iphone', 'Кои твърдения за системите на Apple са верни?', ['iOS се използва на iPhone.', 'iPadOS е предназначена за iPad.', 'iOS е приложение само за снимки.', 'Плъзгачите и бутоните са елементи на интерфейса.', 'Всеки телефон на всяка марка използва iOS.', 'Apple разработва iPhone и неговата операционна система.'], [0, 1, 3, 5], 'iOS е операционната система на iPhone, а iPadOS е предназначена за iPad. Бутоните и плъзгачите са средства за управление. Приложението за снимки изпълнява конкретна задача в средата, която системата осигурява.')

info('harmony', 'HarmonyOS: взаимодействие между устройства', picture('harmony') + '''<p><strong>HarmonyOS</strong> е операционна система, разработвана от <strong>Huawei</strong> и представена през 2019 г. Използва се в съвместими устройства като смартфони, таблети, смартчасовници и смарттелевизори.</p><p>Важна идея е различни устройства да <strong>работят съвместно</strong>. При поддържани модели и подходящи настройки можеш например да прехвърлиш възпроизвеждането на съдържание или да обменяш данни между устройства.</p><p>Възможностите зависят от <strong>модела, версията на системата и региона</strong>. Не можем да заключим операционната система само от надписа Huawei върху корпуса. Проверяваме я в настройките на конкретното устройство.</p><div class="key">Android, iOS и HarmonyOS изпълняват сходна основна задача: управляват устройството и предоставят среда за приложения. Различават се по съвместимите устройства, програмите и конкретните средства за работа.</div>''')
choice('harmony-check', 'harmony', 'Кои твърдения за HarmonyOS и мобилните системи са верни?', ['HarmonyOS се разработва от Huawei.', 'Съвместими устройства могат да обменят данни и да работят заедно.', 'Еднаквата марка гарантира всички функции на всяко устройство.', 'Моделът и версията могат да влияят на възможностите.', 'Операционната система е същото като металния корпус.', 'Android, iOS и HarmonyOS осигуряват среда за приложения.'], [0, 1, 3, 5], 'HarmonyOS е система на Huawei. Съвместната работа зависи от конкретните модели и версии. Операционната система е софтуер; марката върху корпуса не е достатъчна, за да установим всички функции или точната система.')

info('os-practice', 'Практическо наблюдение: коя система използваме?', gallery('android', 'iphone', 'harmony') + '''<p>За да установиш системата на телефон, отвори приложението <strong>„Настройки“</strong>. При Android потърси <strong>„За телефона“ / „Относно телефона“</strong>, а при iPhone — <strong>„Основни“ → „Информация“</strong>. Названията могат да се различават според версията. Ако не виждаш раздела, използвай търсенето в настройките с думата „версия“.</p><p>За общо наблюдение може да се използва споделена таблица с колони <strong>„Участник“ и „Операционна система“</strong>. Всеки попълва само своя ред, например „Участник 1 — Android“. Достатъчно е името на системата.</p><p>Ако нямаш достъп до устройство или обща таблица, използвай този <strong>учебен пример</strong>:</p><table><tr><th>Операционна система</th><th>Брой устройства в примерната група</th></tr><tr><td>Android</td><td>6</td></tr><tr><td>iOS</td><td>3</td></tr><tr><td>HarmonyOS</td><td>1</td></tr></table><p>Общият брой е <strong>10</strong>. Android е при 6 от 10 устройства, тоест <strong>60%</strong> от тази група. Данните описват само примерната група. За световно сравнение са нужни по-широко изследване, посочени период и показател.</p>''')
opened('os-answer', 'intro', 'Направи извод от данните', 'Какъв извод за разпространението на операционните системи можеш да направиш от примерната група с 6 Android, 3 iOS и 1 HarmonyOS?', 'В примерната група Android е най-разпространена: използва се на 6 от общо 10 устройства, или 60%. iOS е на 3, а HarmonyOS — на 1 устройство. Този резултат описва само тази група и не доказва какво е разпространението в целия свят.')

info('wifi', 'Wi-Fi: връзка с локална мрежа', picture('wifi') + '''<p><strong>Wi-Fi</strong> е технология за безжично свързване на устройства в локална мрежа. Телефонът или лаптопът обменя радиосигнали с <strong>точка за достъп</strong>, която често е част от домашния рутер.</p><div class="flow">Телефон ↔ Wi-Fi точка за достъп / рутер ↔ интернет връзка</div><p>Когато рутерът има работеща връзка с интернет, устройството може да използва нея. Самото свързване към Wi-Fi обаче не доказва, че интернет е достъпен. Локалната мрежа може да работи и без външна интернет връзка.</p><p>За свързване отвори <strong>Настройки → Wi-Fi</strong>, избери разрешената мрежа и въведи паролата, ако се изисква. След успешното свързване се появява знакът за Wi-Fi.</p><div class="example">Вкъщи телефонът е свързан към рутера чрез Wi-Fi. Ако интернет връзката на рутера прекъсне, Wi-Fi знакът може да остане, но онлайн страницата няма да се зареди.</div>''')
choice('wifi-check', 'wifi', 'Кои твърдения за Wi-Fi са верни?', ['Wi-Fi свързва устройства безжично в локална мрежа.', 'Точката за достъп може да е част от рутера.', 'Wi-Fi знакът винаги доказва работещ интернет.', 'За някои мрежи е необходима парола.', 'Wi-Fi е името на всички GPS спътници.', 'Локална Wi-Fi мрежа може да работи и без интернет.'], [0, 1, 3, 5], 'Wi-Fi е безжична локална връзка, обикновено през точка за достъп или рутер. Интернет е отделна услуга: знакът за Wi-Fi показва локална връзка, но не гарантира достъп до онлайн страници.')

info('bluetooth', 'Bluetooth: връзка с близки устройства', picture('bluetooth') + '''<p><strong>Bluetooth</strong> е технология за безжичен обмен на данни между устройства. В ежедневието често я използваме на малко разстояние: телефон със слушалки, таблет с клавиатура или телефон със смартчасовник.</p><p><strong>Сдвояване</strong> означава устройствата да се разпознаят и да установят разрешена връзка. За слушалки обикновено включваш техния режим за сдвояване, отваряш <strong>Настройки → Bluetooth</strong> на телефона и избираш името им. Точните действия зависят от модела.</p><p>Bluetooth не изисква непременно интернет. Телефонът може да изпрати към слушалките звук от вече записана песен. Ако слушаш музика онлайн, интернет е нужен за получаването ѝ, а Bluetooth — за звука до слушалките.</p><div class="key">Различните технологии могат да работят заедно: получаваш песента през Wi-Fi, а я слушаш чрез Bluetooth слушалки.</div>''')
choice('bluetooth-check', 'bluetooth', 'Кои твърдения за Bluetooth са верни?', ['Може да свърже телефон и безжични слушалки.', 'Сдвояването установява връзка между устройствата.', 'Всяка Bluetooth връзка изисква мобилен интернет.', 'Записана песен може да се слуша през Bluetooth без интернет.', 'Bluetooth заменя GPS спътниците.', 'Wi-Fi и Bluetooth могат да се използват едновременно за различни части от една задача.'], [0, 1, 3, 5], 'Bluetooth свързва устройства като телефон и слушалки. За записана песен не е необходим интернет. При онлайн музика интернет доставя песента до телефона, а Bluetooth пренася звука към слушалките.')

info('gps', 'GPS: определяне на местоположение', picture('gps') + '''<p><strong>GPS</strong> е спътникова система за определяне на местоположение. Спътниците изпращат радиосигнали с информация за времето и положението си. GPS приемникът в телефона използва сигнали от няколко спътника, за да изчисли къде се намира.</p><div class="flow">Спътници → сигнали → GPS приемник → изчислено местоположение</div><p>Обикновеният GPS приемник <strong>не изпраща обратно съобщение до спътниците</strong>. Приемането на GPS сигнал не изисква мобилен интернет. Интернет обаче може да помогне за по-бързо намиране на мястото или да се използва за изтегляне на карти и актуална информация.</p><p><strong>Местоположението и картата са различни неща.</strong> При предварително изтеглена карта приложение може да показва GPS позицията и без интернет. В помещение или между високи сгради сигналът може да е затруднен.</p><div class="example">На разходка телефонът показва мястото ти върху изтеглена карта. GPS помага да се определи позицията, а картата е изображението на района.</div>''')
choice('gps-check', 'gps', 'Кои твърдения за GPS са верни?', ['Приемникът използва сигнали от спътници.', 'GPS се използва за определяне на местоположение.', 'Всеки GPS приемник изпраща съобщение до спътниците.', 'GPS сигналът и изтеглянето на карта са различни неща.', 'GPS винаги изисква мобилен интернет.', 'Предварително изтеглена карта може да се използва с GPS без интернет.'], [0, 1, 3, 5], 'GPS приемникът получава сигнали и изчислява местоположение. Не е необходим обратен сигнал до спътниците или задължително мобилен интернет. Картите могат да са изтеглени предварително; получаването им онлайн е отделен обмен.')

info('connections', 'Избери подходящата технология', gallery('wifi', 'bluetooth', 'gps') + '''<p>Преди да избереш технология, определи <strong>каква задача изпълняваш</strong>. Сходната дума „безжично“ не означава еднакво предназначение.</p><table><tr><th>Задача</th><th>Подходяща технология</th><th>Защо</th></tr><tr><td>Отваряне на учебен сайт през домашния рутер</td><td><strong>Wi-Fi</strong></td><td>Свързва устройството към локалната мрежа; рутерът осигурява достъпа до интернет.</td></tr><tr><td>Слушане със сдвоени безжични слушалки</td><td><strong>Bluetooth</strong></td><td>Пренася звука между близките устройства.</td></tr><tr><td>Намиране на позицията върху карта</td><td><strong>GPS</strong></td><td>Приемникът изчислява местоположението по спътникови сигнали.</td></tr><tr><td>Мобилен интернет по време на пътуване, без Wi-Fi</td><td><strong>Клетъчна мрежа</strong></td><td>Телефонът използва базовите станции на оператора.</td></tr></table><p>Една ситуация може да използва няколко технологии. При пътуване GPS определя позицията, мобилните данни доставят актуална информация, а Bluetooth предава указанията към слушалките.</p><p>За допълнително проучване: <a href="https://bg.wikipedia.org/wiki/Wi-Fi">Wi-Fi</a>, <a href="https://bg.wikipedia.org/wiki/Bluetooth">Bluetooth</a> и <a href="https://bg.wikipedia.org/wiki/GPS">GPS</a>.</p>''')
choice('connections-check', 'intro', 'Кои избори са подходящи за посочената задача?', ['Домашен рутер към телефон — Wi-Fi.', 'Телефон към безжични слушалки — Bluetooth.', 'Определяне на позиция по спътникови сигнали — GPS.', 'GPS — изтегляне на всички снимки от интернет.', 'Мобилен интернет без Wi-Fi — клетъчна мрежа.', 'Bluetooth — връзка на телефона с GPS спътниците.'], [0, 1, 2, 4], 'Wi-Fi е за локалната безжична мрежа, Bluetooth — за устройства като слушалки, GPS — за местоположение, а клетъчната мрежа — за мобилна връзка през базови станции. GPS не е интернет услуга за изтегляне на снимки.')

info('summary', 'Най-важното от урока', picture('intro') + '''<ul><li><strong>Мобилните устройства</strong> са преносими компютърни устройства; смартфонът съчетава телефон и приложения.</li><li><strong>Клетъчната мрежа</strong> използва базови станции, които осигуряват радиопокритие в клетки.</li><li><strong>1G–5G</strong> означават поколения мобилни технологии; реалната скорост зависи и от условията.</li><li><strong>Android, iOS и HarmonyOS</strong> управляват устройства и осигуряват среда за приложения; точната система се проверява в настройките.</li><li><strong>Wi-Fi</strong> свързва към локална мрежа, <strong>Bluetooth</strong> — към устройства като слушалки, а <strong>GPS</strong> помага да определим местоположението.</li></ul>''')

